// Generate an iCalendar (.ics) file for the booking
const transaction = $('Transaction Transitioned').first().json;
const resource = transaction.resource;

// Extract booking dates from transaction resource
// Update these field paths based on your transaction data structure
const bookingStart = resource.bookingStart || resource.booking?.start || new Date().toISOString();
const bookingEnd = resource.bookingEnd || resource.booking?.end || new Date().toISOString();
const listingTitle = resource.listingTitle || 'Marketplace Booking';
const transactionId = transaction.resourceId;

// Format dates for iCalendar (YYYYMMDDTHHmmssZ)
function formatIcsDate(isoDate) {
  return new Date(isoDate).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
}

const now = formatIcsDate(new Date().toISOString());
const start = formatIcsDate(bookingStart);
const end = formatIcsDate(bookingEnd);

// Build the .ics content
const icsContent = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//Sharetribe Marketplace//n8n Workflow//EN',
  'CALSCALE:GREGORIAN',
  'METHOD:PUBLISH',
  'BEGIN:VEVENT',
  `DTSTART:${start}`,
  `DTEND:${end}`,
  `DTSTAMP:${now}`,
  `UID:${transactionId}@sharetribe-marketplace`,
  `SUMMARY:${listingTitle}`,
  `DESCRIPTION:Booking confirmed for ${listingTitle}. Transaction ID: ${transactionId}`,
  'STATUS:CONFIRMED',
  'PRIORITY:1',
  'END:VEVENT',
  'END:VCALENDAR',
].join('\r\n');

// Convert to base64 for binary attachment
const base64Content = Buffer.from(icsContent).toString('base64');

return [
  {
    json: {
      ...transaction,
      icsContent,
      bookingStart,
      bookingEnd,
      listingTitle,
    },
    binary: {
      data: {
        data: base64Content,
        mimeType: 'text/calendar',
        fileName: `booking-${transactionId.substring(0, 8)}.ics`,
      },
    },
  },
];

